// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CombatEntry) predicate.CombatEntry {
	return predicate.CombatEntry(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CombatEntry) predicate.CombatEntry {
	return predicate.CombatEntry(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CombatEntry) predicate.CombatEntry {
	return predicate.CombatEntry(sql.NotPredicates(p))
}
